(() => {
  const g = __rhf.game;
  g.state.settings.autoQuality = false;
  g.setQuality('high');
  g.dpr = 1;
  g.renderer.setPixelRatio(1);
  g.resize();
  g.bears.directorT = 1e9;
  const we = g.env.weather;
  we.cloud = we.cloudTarget = 0.25;
  we.rain = we.rainTarget = 0;
  we.timer = 1e9;
  g.env.timeScale = 0;
  g.env.setTime(10.5);
  g.hud.firstShown = -1000;
  g.hud.hint('', 0);
  g.hud.show(false);
  __rhf.god(true);
  g.wildlife.threatPos = () => ({ x: 1e7, z: 1e7, loud: 0 });
  g.player.tool = 'none';
  g.viewmodel.setTool('none');
  // stand dist metres from a point, in the direction ang from its front, and look at it
  window.__look = (cx, cy, cz, front, ang, dist, time = 10.5) => {
    const P = g.player;
    g.env.setTime(time);
    const x = cx + Math.sin(front + ang) * dist;
    const z = cz + Math.cos(front + ang) * dist;
    P.place(x, z, 0);
    const ey = P.pos.y + 1.66;
    P.yaw = Math.atan2(-(cx - x), -(cz - z));
    P.pitch = Math.atan2(cy - ey, Math.hypot(cx - x, cz - z));
    __rhf.settle();
    return 'at ' + x.toFixed(1) + ',' + z.toFixed(1) + ',' + P.pos.y.toFixed(2) + ' looking at ' + cx.toFixed(1) + ',' + cz.toFixed(1);
  };
  const L = g.props.layout;
  return 'cabin ' + JSON.stringify(L.cabin) + ' post ' + JSON.stringify(L.post);
})()
